// Verifies the X-OFD-Signature header (HMAC-SHA256 over "<timestamp>.<raw body>").
// Paste the signing secret shown when you created the webhook in OpenFrontDesk.
const SECRET = 'whsec_REPLACE_ME';

const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers;
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');
const ts = headers['x-ofd-timestamp'];
const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(`${ts}.`).update(raw).digest('hex');
const received = headers['x-ofd-signature'] || '';
const valid = received.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
if (!valid) throw new Error('Invalid OpenFrontDesk signature');
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('Stale OpenFrontDesk event');

return [{ json: JSON.parse(raw.toString('utf8')) }];

